"""External fake KMS: works like local but delete() honors a flag file.

When /tmp/brfake/delete_fails exists, delete raises; otherwise it succeeds
and removes the registry entry. Material is held in an in-memory + JSON
registry under the data directory so a server restart keeps the handles.
"""
import json
import os
import threading
import uuid

FLAG = os.environ.get("BR_FAKE_FLAG", "/tmp/brfake/delete_fails")
REG = os.path.join(os.environ.get("BR_FAKE_DIR", "/tmp/brfake"), "reg.json")
_LOCK = threading.Lock()


class FakeProvider:
    provider_id = "fake-1"
    capabilities = {
        "algorithms": ["AES256", "RSA2048"],
        "operations": ["generate", "rotate", "import_material",
                       "export_material", "delete"],
    }

    def __init__(self):
        self._dir = None
        self._reg = {}

    def configure(self, data_dir):
        self._dir = data_dir
        try:
            with open(REG) as fh:
                self._reg = json.load(fh)
        except (OSError, ValueError):
            self._reg = {}

    def _persist(self):
        os.makedirs(os.path.dirname(REG), exist_ok=True)
        tmp = REG + ".tmp"
        with open(tmp, "w") as fh:
            json.dump(self._reg, fh)
        os.replace(tmp, REG)

    @staticmethod
    def _keypair(algorithm):
        from cryptography.hazmat.primitives.asymmetric import rsa
        from cryptography.hazmat.primitives import serialization
        if algorithm == "AES256":
            material = __import__("base64").b64encode(os.urandom(32)).decode()
            return material, None
        key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        priv = key.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.TraditionalOpenSSL,
            serialization.NoEncryption()).decode()
        pub = key.public_key().public_bytes(
            serialization.Encoding.PEM,
            serialization.PublicFormat.SubjectPublicKeyInfo).decode()
        return priv, pub

    def generate(self, algorithm):
        material, pub = self._keypair(algorithm)
        handle = uuid.uuid4().hex
        with _LOCK:
            self._reg[handle] = {"algorithm": algorithm, "material": material}
            self._persist()
        return {"handle": handle, "public_key": pub,
                "encrypted_material": "enc:" + handle}

    def rotate(self, algorithm):
        return self.generate(algorithm)

    def import_material(self, algorithm, public_key, material):
        return self.generate(algorithm)

    def export_material(self, handle):
        meta = self._reg.get(handle)
        if meta is None:
            raise RuntimeError("unknown handle")
        return {"public_key": None, "encrypted_material": meta["material"]}

    def delete(self, handle):
        if os.path.exists(FLAG):
            raise RuntimeError("backend delete unavailable")
        with _LOCK:
            self._reg.pop(handle, None)
            self._persist()


def factory():
    return FakeProvider()

